import { For, onCleanup, onMount, Show, useContext } from "solid-js";

import { CollapsibleContainer } from "#core/ui-next/components/collapsible-container.jsx";
import { Divider } from "#core/ui-next/components/divider.jsx";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { InnerFrame } from "#core/ui-next/components/inner-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot } from "#core/ui-next/components/slot.jsx";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";

import { DedicationCard } from "#base/ui-next/screens/legacies/dedication-selection.jsx";
import { DedicationsFilterOptions, DedicationsModel } from "#base/ui-next/screens/legacies/dedications-model.js";

export const DedicationTab = () => {
	const dropdownDedicationItems = [
		"ALL",
		"DEFAULT",
		"CULTURAL",
		"DIPLOMATIC",
		"ECONOMIC",
		"EXPANSIONIST",
		"MILITARISTIC",
		"SCIENTIFIC",
		"CRISIS",
	];

	const model = DedicationsModel.get();
	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		hotkeyContext.registerNavtray("shell-action-2", "LOC_ADVANCED_START_FILTER");
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("shell-action-2");
	});

	return (
		<div
			class="px-10 pb-2 flex flex-auto flex-col"
			classList={{
				"px-10": !model.isSmallScreen(),
				"px-4": model.isSmallScreen(),
			}}
		>
			<div class="text-accent-2 text-xs w-full text-center my-1">
				<L10n.Compose text="LOC_DEDICATIONS_DESC" />
			</div>
			<InnerFrame
				class="px-2 py-3 flex-auto"
				style={{
					"background-image":
						"linear-gradient(rgba(20, 20, 20, 0.8), rgba(20, 20, 20, 0.7), rgba(20, 20, 20, 0.8))",
				}}
			>
				<CollapsibleContainer
					titleText={
						GameInfo.Ages.lookup(Game.age)?.AgeType != "AGE_ANTIQUITY" &&
						Configuration.getGame().previousAgeCount == 0
							? "LOC_DEDICATIONS_ACTIVE_LEGACIES"
							: "LOC_DEDICATIONS_ACTIVE_DEDICATIONS"
					}
					class="w-full"
					headerClass="fxs-header text-gradient-base"
					centerTitle
					disabled={!model.isPlacementComplete() || model.state.selectedItems.length <= 0}
				>
					<div
						class="flex my-2"
						classList={{
							"flex-auto": model.isPlacementComplete() && model.state.selectedItems.length > 0,
						}}
					>
						<Show when={!model.isPlacementComplete() || model.state.selectedItems.length <= 0}>
							<div class="flex items-center justify-center text-accent-3 text-base w-full text-center min-h-38">
								<L10n.Compose text="LOC_DEDICATIONS_EMPTY_DESC" />
							</div>
						</Show>
						<Show when={model.isPlacementComplete() && model.state.selectedItems.length > 0}>
							<div
								class="flex justify-center flex-auto flex-wrap p-1"
								classList={{
									"items-start":
										GameInfo.Ages.lookup(Game.age)?.AgeType != "AGE_ANTIQUITY" &&
										Configuration.getGame().previousAgeCount == 0,
								}}
							>
								<For
									each={model.state.items.filter((item) =>
										model.state.selectedItems.some((selected) => selected.info.id == item.id),
									)}
								>
									{(card) => (
										<DedicationCard
											id={card.id}
											class="m-3"
											title={card.title}
											description={card.description}
											background={card.descriptionBG}
											icon={card.traitIcon}
											isDisplayOnly
										/>
									)}
								</For>
							</div>
						</Show>
					</div>
				</CollapsibleContainer>
				<CollapsibleContainer
					titleText={
						GameInfo.Ages.lookup(Game.age)?.AgeType != "AGE_ANTIQUITY" &&
						Configuration.getGame().previousAgeCount == 0
							? "LOC_DEDICATIONS_ADVANCED_START_LEGACIES"
							: "LOC_DEDICATIONS_AVAILABLE_DEDICATIONS"
					}
					class="flex flex-col items-center flex-auto w-full"
					headerClass="fxs-header text-gradient-base"
					disabled={Game.AgeProgressManager.isFinalAge}
					centerTitle
				>
					<Show
						when={!Game.AgeProgressManager.isFinalAge}
						fallback={
							<div
								class="flex justify-center text-accent-2 text-base w-full m-6 p-3"
								style={{
									border: "1px solid",
									"border-image-slice": "1",
									"border-width": "1px",
									"border-image-source":
										"linear-gradient(to right, rgba(85, 85, 85, 0), rgba(85, 85, 85, 1), rgba(85, 85, 85, 0))",
									"background-image":
										"linear-gradient(to right, rgba(42, 42, 48, 0), rgba(42, 42, 48, 1), rgba(42, 42, 48, 0))",
								}}
							>
								<L10n.Compose text="LOC_DEDICATIONS_FINAL_AGE_DESC" />
							</div>
						}
					>
						<div class="flex w-full justify-end px-6 mt-2 items-center">
							<HSlot class="flex">
								<div class="flex items-center">
									<Header class={`uppercase text-sm text-secondary font-title`}>
										<L10n.Compose text="LOC_ADVANCED_START_FILTER" />
									</Header>
									<Dropdown
										disableFocus
										class="ml-2 w-60 pointer-events-auto grow-0"
										selectedItemTemplate={(item) => (
											<span class="m-1">
												<L10n.Stylize text={Locale.compose(`LOC_LEGACIES_FILTER_${item}`)} />
											</span>
										)}
										defaultValue={DedicationsFilterOptions.ALL}
										onItemSelected={(item) => model.setSelectedDedicationFilter(item)}
										hotkey="shell-action-2"
									>
										<For each={dropdownDedicationItems}>
											{(item) => (
												<DropdownItem value={item}>
													<L10n.Stylize
														text={Locale.stylize(`LOC_LEGACIES_FILTER_${item}`)}
													/>
												</DropdownItem>
											)}
										</For>
									</Dropdown>
								</div>
							</HSlot>
						</div>
						<Divider.Horizontal class="w-full h-0\\.5 my-2" />
						<ScrollArea
							class="flex-auto"
							useProxy
						>
							<div class="flex justify-center items-start flex-wrap p-1">
								<For each={model.state.legacies}>
									{(card) => (
										<Show
											when={card.filterOptions?.find((filter) => {
												return filter == model.selectedDedicationFilter();
											})}
										>
											<DedicationCard
												id={card.id}
												class="m-3"
												title={card.title}
												description={card.description}
												background={card.descriptionBG}
												icon={card.traitIcon}
												disabled={card.isDisabled}
												isDisplayOnly
											/>
										</Show>
									)}
								</For>
							</div>
						</ScrollArea>
					</Show>
				</CollapsibleContainer>
			</InnerFrame>
		</div>
	);
};
